 out=D/'MONITOR_H1_V2_FIRST_REAL_PPO_ACTUAL64_SHA_BOUND_UTF8LF_V4_20261016.txt';assert not out.exists();args=json.loads((D/'AUTOMATION_UPDATE_H1_V2_FIRST_REAL_PPO_VERIFIED_V3_ARGS.json').read_bytes());proof=json.loads((R/'V2_ACTUAL_NATIVE_MODELS_FIRST_IMMUTABLE_PRODUCTION_LOCAL_CPU_VERIFIED.json').read_bytes());row=next(x for x in proof['models'] if x['role']=='production/model_update1.pt');actual=row['SHA'];assert re.fullmatch('[0-9a-f]{64}',actual);raw=Path(row['path']).read_bytes();assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==actual;bad='c5fb7ffa5b316f89415cf96982e4da23dda89efabd470a00cd9a1fa33226fa4d9';assert len(bad)==65 and bad in args['prompt'];report=dict(epoch=time.time(),original_V3_monitor_transcription_rejected_before_app_update=True,original_65_character_first_model_SHA=bad,actual64_first_model_SHA=actual,actual_model_path=row['path'],actual_bytes=row['bytes'],actual_model_SHA_independent_fullbytes_verified=True,no_runtime_model_or_CPU_result_changed=True,original_V3_monitor_source_and_failure_retained=True);(R/'V3_MONITOR_65CHAR_SHA_TRANSCRIPTION_REJECTED_ACTUAL64_READER_V4_FIX.json').write_text(json.dumps(report,indent=2),encoding='utf8');text='最新V4 actual工具64SHA绑定：V3本机监控writer把first model SHA手填成65位，已在app更新前拒绝，原件/拒绝与独立V4修复并列保存，非模型/GPU/物理故障。此V4直接从完整模型工具CPU回执提取64位并重新核完整本机bytes，正确first model SHA='+actual+'，其余V3真实PPO/成本pending范围不变。以下V3叙述中该字串仅在本V4文本独立修正，原V3文件原样保留；后来actual/newhuman优先：\n\n'+args['prompt'].replace(bad,actual);out.write_text(text,encoding='utf8',newline='\n');args['prompt']=text;(D/'AUTOMATION_UPDATE_H1_V2_FIRST_REAL_PPO_ACTUAL64_V4_ARGS.json').write_text(json.dumps(args,ensure_ascii=False,indent=2),encoding='utf8');work=json.loads((D/'NEXT_H1_V2_FIRST_REAL_PRODUCTION_VERIFIED_SAME_ONE1800_WINDOW_ACTUAL_V3_WORK_ORDER.json').read_bytes());work.update(actual_first_model64SHA_bound=True,rejected_V3_65char_monitor_not_installed=True,monitor=dict(path=str(out),bytes=out.stat().st_size,SHA=hashlib.sha256(out.read_bytes()).hexdigest()));(D/'NEXT_H1_V2_FIRST_REAL_PPO_MODEL64SHA_BOUND_SAME_WINDOW_ACTUAL_V4_WORK_ORDER.json').write_text(json.dumps(work,indent=2),encoding='utf8');print(json.dumps(dict(actual_model64SHA=actual,monitor_SHA=work['monitor']['SHA'],original_V3_failure_retained=True)))
